import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int count = scanner.nextInt();
        List<Integer> data = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            data.add(scanner.nextInt());
        }
        Collections.sort(data);
        int limit = scanner.nextInt();
        int maxGroup = -1;
        for (int i = 0; i < count; i++) {
            int upperBoundIdx = upperBound(data, data.get(i) + limit);
            maxGroup = Math.max(maxGroup, upperBoundIdx - i);
        }
        System.out.println(maxGroup);
    }

    private static int upperBound(List<Integer> data, int value) {
        int low = 0, high = data.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (data.get(mid) > value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
